//! Explicit file operation; no Session mutation, codec or GUI filesystem call.
//! One batch owner, including all blocked IO/retirement, is admitted globally.
mod matroska;
use serde::{Serialize,Deserialize};
use std::{fs::{self,File,OpenOptions,},io::{self,Read,Write,Seek,SeekFrom},path::{Path,PathBuf},sync::{Arc,Mutex,atomic::{AtomicU64,AtomicUsize,AtomicU8,AtomicBool,Ordering}},thread};
use skylive_mp4::{SpoolLimits,SpoolMp4Writer,WriterOptions,Brand,SampleEntry,TrackConfig,ColorInfo};
pub const MAX_JOBS:usize=32;
pub const MAX_PATH_BYTES:usize=4096;
const FILE_BYTES:u64=64*1024*1024*1024;
static NEXT:AtomicU64=AtomicU64::new(1);
static OWNERS:AtomicUsize=AtomicUsize::new(0);
struct Permit;
impl Drop for Permit{fn drop(&mut self){OWNERS.fetch_sub(1,Ordering::AcqRel);}}
#[derive(Clone,Debug,Serialize,Deserialize)]pub struct Job{pub source:PathBuf,pub destination:PathBuf}
#[derive(Clone,Copy,Debug,PartialEq,Eq,Serialize,Deserialize)]pub struct Key(pub u64);
#[derive(Clone,Copy,Debug,PartialEq,Eq,Serialize)]pub enum Phase{Queued,Opening,Reading,Finalizing,Publishing,Complete,Canceled,Failed,NotStarted}
#[derive(Clone,Debug,Serialize)]pub struct Receipt{pub job:usize,pub source:PathBuf,pub destination:PathBuf,pub phase:Phase,pub failed_at:Option<Phase>,pub source_identity:Option<SourceIdentity>,pub input_bytes:u64,pub processed_bytes:u64,pub packets:u64,pub video_packets:u64,pub audio_packets:u64,pub duration_100ns:Option<u64>,pub audio_valid_end_ns:Option<u64>,pub output_bytes:u64,pub private_output:Option<PathBuf>,pub private_spool:Option<PathBuf>,pub recovery_note:Option<PathBuf>,pub published:bool,pub error:Option<String>}
impl Receipt{fn new(job:usize,j:&Job)->Self{Self{job,source:j.source.clone(),destination:j.destination.clone(),phase:Phase::Queued,failed_at:None,source_identity:None,input_bytes:0,processed_bytes:0,packets:0,video_packets:0,audio_packets:0,duration_100ns:None,audio_valid_end_ns:None,output_bytes:0,private_output:None,private_spool:None,recovery_note:None,published:false,error:None}}}
#[derive(Clone,Debug,Default,Serialize)]pub struct Status{pub key:Option<Key>,pub active:bool,pub cancel_requested:bool,pub retired:bool,pub current:Option<usize>,pub receipts:Vec<Receipt>,pub failure:Option<String>}
struct Shared{status:Mutex<Status>,cancel:AtomicBool,commit:AtomicU8,retired:AtomicBool,wake:Arc<dyn Fn()+Send+Sync>}
struct Run{key:Key,state:Arc<Shared>,_thread:thread::JoinHandle<()>}
#[derive(Default)]pub struct Owner{run:Option<Run>,cached:Status}
pub fn capabilities()->serde_json::Value{serde_json::json!({"operation":"remux_recordings","input":"finalized_skylive_mkv_v4","output":"mp4","video":"avc8_baseline_high_progressive_sdr709_no_b","audio":"optional_aac_lc_mono_stereo_44100_48000","decoder":false,"external_process":false,"max_jobs":MAX_JOBS,"max_input_bytes":FILE_BYTES,"max_duration_seconds":86400,"overwrite":false,"runtime_verified":false})}
fn validate(jobs:&[Job])->Result<(),String>{if jobs.is_empty()||jobs.len()>MAX_JOBS{return Err("Remux queue must contain1..32jobs".into());}for(index,job)in jobs.iter().enumerate(){for path in [&job.source,&job.destination]{let s=path.to_str().ok_or("Remux paths must be Unicode")?;if s.is_empty()||s.len()>MAX_PATH_BYTES||s.chars().any(char::is_control)||path.file_name().is_none(){return Err("Remux path exceeds bounded file-operation contract".into());}}if !job.source.extension().and_then(|s|s.to_str()).is_some_and(|s|s.eq_ignore_ascii_case("mkv"))||!job.destination.extension().and_then(|s|s.to_str()).is_some_and(|s|s.eq_ignore_ascii_case("mp4"))||job.source==job.destination{return Err("Remux requires distinct .mkv source and .mp4 destination".into());}if jobs[..index].iter().any(|other|other.destination==job.destination){return Err("Remux queue contains duplicate destinations".into());}}Ok(())}
impl Owner{
    pub fn start(&mut self,jobs:Vec<Job>,wake:Arc<dyn Fn()+Send+Sync>)->Result<Key,String>{
        validate(&jobs)?;if self.run.as_ref().is_some_and(|r|!r.state.retired.load(Ordering::Acquire)){return Err("Remux owner is active or retiring".into());}
        OWNERS.compare_exchange(0,1,Ordering::AcqRel,Ordering::Acquire).map_err(|_|"Remux owner is active or retiring")?;let permit=Permit;
        let key=Key(NEXT.fetch_update(Ordering::AcqRel,Ordering::Acquire,|v|v.checked_add(1)).map_err(|_|"Remux identity exhausted")?);
        let initial=Status{key:Some(key),active:true,receipts:jobs.iter().enumerate().map(|(n,j)|Receipt::new(n,j)).collect(),..Default::default()};let state=Arc::new(Shared{status:Mutex::new(initial.clone()),cancel:AtomicBool::new(false),commit:AtomicU8::new(0),retired:AtomicBool::new(false),wake});let shared=state.clone();
        let handle=thread::Builder::new().name("skylive-recording-remux".into()).spawn(move||{
            let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||batch(key,&jobs,&shared)));
            if let Err(payload)=result{let detail=payload.downcast_ref::<String>().map(String::as_str).or_else(||payload.downcast_ref::<&str>().copied()).unwrap_or("non-string panic payload");eprintln!("Remux worker panicked: {detail}");update(&shared,|s|{s.failure=Some("Remux worker panicked; exact details are in the host log. Private files are retained.".into());for r in &mut s.receipts{if !matches!(r.phase,Phase::Complete|Phase::Failed|Phase::Canceled){r.failed_at=Some(r.phase);r.phase=Phase::Failed;r.error=Some("Remux worker retired unexpectedly; no completion is claimed.".into());}}});}
            // All batch inputs/mux/spool handles have dropped before admission
            // and actual-retirement publication, including cancellation/panic.
            drop(jobs);update(&shared,|s|{s.active=false;s.retired=true;s.current=None;});let _=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||(shared.wake)()));drop(permit);shared.retired.store(true,Ordering::Release);
        }).map_err(|e|e.to_string())?;
        self.cached=initial;self.run=Some(Run{key,state,_thread:handle});Ok(key)
    }
    pub fn status(&mut self)->Status{if let Some(run)=&self.run{if let Ok(s)=run.state.status.try_lock(){self.cached=s.clone();}self.cached.cancel_requested=run.state.cancel.load(Ordering::Acquire);self.cached.retired=run.state.retired.load(Ordering::Acquire);self.cached.active=!self.cached.retired;}self.cached.clone()}
    pub fn cancel(&self,key:Key)->Result<(),String>{let run=self.run.as_ref().filter(|r|r.key==key).ok_or("Remux batch identity is obsolete")?;if run.state.retired.load(Ordering::Acquire){return Ok(());}run.state.cancel.store(true,Ordering::Release);let _=run.state.commit.compare_exchange(0,1,Ordering::AcqRel,Ordering::Acquire);Ok(())}
    pub fn close(&self){if let Some(r)=&self.run{let _=self.cancel(r.key);}}
    pub fn is_retired(&self)->bool{self.run.as_ref().is_none_or(|r|r.state.retired.load(Ordering::Acquire))}
}
impl Drop for Owner{fn drop(&mut self){self.close();}}
fn update(shared:&Shared,f:impl FnOnce(&mut Status)){if let Ok(mut s)=shared.status.lock(){f(&mut s);}}
fn publish(shared:&Shared,receipt:&Receipt){update(shared,|s|{s.cancel_requested=shared.cancel.load(Ordering::Acquire);if let Some(row)=s.receipts.get_mut(receipt.job){*row=receipt.clone();}});(shared.wake)();}
fn canceled(shared:&Shared)->io::Result<()>{if shared.cancel.load(Ordering::Acquire){Err(io::Error::new(io::ErrorKind::Interrupted,"Remux canceled; private prefix is retained"))}else{Ok(())}}
/// Codec/container ports honor cancellation during bounded scans/finalization.
/// This cannot interrupt a blocked OS IO; the retiring permit remains held.
struct Port{file:File,shared:Arc<Shared>}
impl Read for Port{fn read(&mut self,b:&mut[u8])->io::Result<usize>{canceled(&self.shared)?;let n=b.len().min(65536);self.file.read(&mut b[..n])}}
impl Write for Port{fn write(&mut self,b:&[u8])->io::Result<usize>{canceled(&self.shared)?;self.file.write(&b[..b.len().min(65536)])}fn flush(&mut self)->io::Result<()>{canceled(&self.shared)?;self.file.flush()}}
impl Seek for Port{fn seek(&mut self,p:SeekFrom)->io::Result<u64>{canceled(&self.shared)?;self.file.seek(p)}}
fn batch(key:Key,jobs:&[Job],shared:&Arc<Shared>){for(index,job)in jobs.iter().enumerate(){if shared.cancel.load(Ordering::Acquire){update(shared,|s|for r in &mut s.receipts[index..]{r.phase=Phase::NotStarted;});break;}
    shared.commit.store(0,Ordering::Release);if shared.cancel.load(Ordering::Acquire){update(shared,|s|for r in &mut s.receipts[index..]{r.phase=Phase::NotStarted;});break;}update(shared,|s|s.current=Some(index));let mut receipt=Receipt::new(index,job);receipt.phase=Phase::Opening;publish(shared,&receipt);
    let result=operation(key,index,job,shared,&mut receipt);
    if let Err(error)=result{let canceled=shared.cancel.load(Ordering::Acquire)&&shared.commit.load(Ordering::Acquire)!=2&&!receipt.published;receipt.failed_at=Some(receipt.phase);receipt.phase=if canceled{Phase::Canceled}else{Phase::Failed};receipt.error=Some(error);if let Some(note)=&receipt.recovery_note{if let Err(error)=recovery(note,&receipt,false){eprintln!("Remux recovery note {}: {error}",note.display());}}}publish(shared,&receipt);
}}
fn source_open(path:&Path)->io::Result<File>{let mut options=OpenOptions::new();options.read(true);#[cfg(target_os="windows")]{use std::os::windows::fs::OpenOptionsExt;options.share_mode(1); /* FILE_SHARE_READ only: deny writes and rename/delete while held. */}options.open(path)}
#[derive(Clone,Debug,PartialEq,Eq,Serialize)]pub struct SourceIdentity{length:u64,modified:Option<std::time::SystemTime>,created:Option<std::time::SystemTime>,#[cfg(target_os="windows")]volume:u32,#[cfg(target_os="windows")]index:u64,#[cfg(unix)]device:u64,#[cfg(unix)]inode:u64}
fn identity(file:&File)->Result<SourceIdentity,String>{let m=file.metadata().map_err(|e|e.to_string())?;
    #[cfg(target_os="windows")]let information={use std::os::windows::io::AsRawHandle;use windows::Win32::{Foundation::HANDLE,Storage::FileSystem::{GetFileInformationByHandle,BY_HANDLE_FILE_INFORMATION}};let mut info=BY_HANDLE_FILE_INFORMATION::default();
        // SAFETY: the owned File remains open for this synchronous worker-only
        // identity read; info is a valid initialized native output structure.
        unsafe{GetFileInformationByHandle(HANDLE(file.as_raw_handle()),&mut info)}.map_err(|e|e.to_string())?;info};
    #[cfg(unix)]use std::os::unix::fs::MetadataExt;
    Ok(SourceIdentity{length:m.len(),modified:m.modified().ok(),created:m.created().ok(),#[cfg(target_os="windows")]volume:information.dwVolumeSerialNumber,#[cfg(target_os="windows")]index:(u64::from(information.nFileIndexHigh)<<32)|u64::from(information.nFileIndexLow),#[cfg(unix)]device:m.dev(),#[cfg(unix)]inode:m.ino()})}
fn operation(key:Key,index:usize,job:&Job,shared:&Arc<Shared>,receipt:&mut Receipt)->Result<(),String>{
    let input=source_open(&job.source).map_err(|e|format!("Open remux source {}: {e}",job.source.display()))?;let source_meta=input.metadata().map_err(|e|e.to_string())?;if !source_meta.is_file()||source_meta.len()<32||source_meta.len()>FILE_BYTES{return Err("Remux input must be a regular32byte..64GiB file".into());}let original=identity(&input)?;receipt.input_bytes=original.length;receipt.source_identity=Some(original.clone());
    let source_path=fs::canonicalize(&job.source).map_err(|e|e.to_string())?;let parent=job.destination.parent().filter(|p|!p.as_os_str().is_empty()).unwrap_or(Path::new("."));let parent=fs::canonicalize(parent).map_err(|e|e.to_string())?;let destination=parent.join(job.destination.file_name().ok_or("Remux destination filename missing")?);if source_path==destination{return Err("Remux source and destination resolve to the same path".into());}match fs::symlink_metadata(&destination){Ok(_)=>return Err("Remux destination already exists; no file was overwritten".into()),Err(e)if e.kind()==io::ErrorKind::NotFound=>{},Err(e)=>return Err(e.to_string())}
    let mut input=std::io::BufReader::with_capacity(65536,Port{file:input,shared:shared.clone()});let mut profile=matroska::open(&mut input,original.length)?;receipt.duration_100ns=Some(profile.duration);
    let name=destination.file_name().and_then(|s|s.to_str()).ok_or("Remux destination filename is not Unicode")?;let mut owned=None;
    for suffix in 0..16{let path=parent.join(format!(".{name}.skylive-remux-{}-{index}-{suffix}.partial.mp4",key.0));match OpenOptions::new().read(true).write(true).create_new(true).open(&path){Ok(file)=>{owned=Some((path,file));break;},Err(e)if e.kind()==io::ErrorKind::AlreadyExists=>{},Err(e)=>return Err(e.to_string())}}
    let(path,file)=owned.ok_or("Cannot exclusively create private remux output after16collision attempts")?;let spool_path=path.with_extension("samples.spool");let note_path=path.with_extension("recovery.txt");receipt.private_output=Some(path.clone());receipt.phase=Phase::Reading;publish(shared,receipt);recovery(&note_path,receipt,true)?;receipt.recovery_note=Some(note_path.clone());
    let spool=OpenOptions::new().read(true).write(true).create_new(true).open(&spool_path).map_err(|e|e.to_string())?;receipt.private_spool=Some(spool_path.clone());let limits=SpoolLimits{max_records:matroska::MAX_PACKETS,max_spool_bytes:SpoolLimits::required_spool_bytes(matroska::MAX_PACKETS).map_err(|e|e.to_string())?,max_output_bytes:FILE_BYTES,max_duration_seconds:86400,max_moov_bytes:512*1024*1024,max_scan_records:matroska::MAX_PACKETS*10};let mut options=WriterOptions::new(Brand::Mp4);options.movie_timescale=1_000_000_000;
    let mut mux=SpoolMp4Writer::new(Port{file,shared:shared.clone()},options,Port{file:spool,shared:shared.clone()},limits).map_err(|e|e.to_string())?;let mut entry=SampleEntry::avc(profile.avcc.clone(),profile.width as u16,profile.height as u16);if let Some(video)=&mut entry.video{video.color=Some(ColorInfo::Nclx{primaries:1,transfer:1,matrix:1,full_range:false});}mux.add_track(TrackConfig::new(entry,10_000_000)).map_err(|e|e.to_string())?;if let Some(a)=&profile.audio{mux.add_track(TrackConfig::new(SampleEntry::aac(a.asc.clone(),u32::from(a.channels),a.rate),1_000_000_000)).map_err(|e|e.to_string())?;}
    let mut last_notice=0;let summary=matroska::transfer(&mut input,&mut profile,&mut mux,|processed,_|{canceled(shared).map_err(|e|e.to_string())?;if processed>=last_notice+1024*1024{last_notice=processed;receipt.processed_bytes=processed.min(receipt.input_bytes);publish(shared,receipt);}Ok(())})?;receipt.packets=summary.packets;receipt.video_packets=summary.video;receipt.audio_packets=summary.audio;receipt.audio_valid_end_ns=summary.audio_valid_end_ns;receipt.processed_bytes=receipt.input_bytes;receipt.phase=Phase::Finalizing;publish(shared,receipt);
    let(mut media,mut spool,finished)=mux.finish().map_err(|e|e.to_string())?;media.flush().and_then(|_|media.file.sync_all()).map_err(|e|e.to_string())?;spool.flush().and_then(|_|spool.file.sync_all()).map_err(|e|e.to_string())?;receipt.output_bytes=finished.output_bytes;drop(media);drop(spool);
    if identity(&input.get_ref().file)?!=original||identity(&source_open(&source_path).map_err(|e|e.to_string())?)?!=original||identity(&source_open(&job.source).map_err(|e|e.to_string())?)?!=original{return Err("Remux source identity/length/timestamps changed during operation; private MP4 retained".into());}recovery(&note_path,receipt,false)?;
    // Cancel wins before this one-way publication claim. Once claimed, a
    // complete private file may publish; late cancel only stops following jobs.
    if shared.cancel.load(Ordering::Acquire)||shared.commit.compare_exchange(0,2,Ordering::AcqRel,Ordering::Acquire).is_err(){return Err("Remux canceled before publication; complete private MP4 retained".into());}
    receipt.phase=Phase::Publishing;publish(shared,receipt);let publication=crate::private_output::publish(&path,&destination).map_err(|e|format!("Publish remux MP4 without overwrite: {e}"))?;receipt.published=true;publication.remove_temporary(&path).map_err(|e|format!("Remux published; private-name cleanup failed: {e}"))?;fs::remove_file(&spool_path).map_err(|e|format!("Remux published; spool cleanup failed: {e}"))?;fs::remove_file(&note_path).map_err(|e|format!("Remux published; recovery-note cleanup failed: {e}"))?;receipt.phase=Phase::Complete;Ok(())
}
fn recovery(path:&Path,receipt:&Receipt,create:bool)->Result<(),String>{let text=format!("SkyLive remux recovery — no repair/playback acceptance claimed\nSource remains unchanged: {}\nDestination: {}\nPhase: {:?} (failed at {:?})\nPrivate MP4: {:?}\nPrivate sample journal: {:?}\nAccepted packets: {}\nFinal output bytes: {}\nPublished: {}\nProblem: {:?}\nKeep the private MP4 and SKYMP4S1 journal together on failure. An interrupted media prefix is not a finalized/playable MP4. Only a complete successful mux finalization and no-overwrite publication is Complete.\n",receipt.source.display(),receipt.destination.display(),receipt.phase,receipt.failed_at,receipt.private_output,receipt.private_spool,receipt.packets,receipt.output_bytes,receipt.published,receipt.error);if text.len()>65536{return Err("Remux recovery note exceeds64KiB".into());}let mut options=OpenOptions::new();options.write(true);if create{options.create_new(true);}else{options.truncate(true);}let mut file=options.open(path).map_err(|e|e.to_string())?;file.write_all(text.as_bytes()).and_then(|_|file.sync_all()).map_err(|e|e.to_string())}
